def solve(coins, amount):
    best = [0] + [None] * amount
    for v in range(1, amount + 1):
        opts = [best[v - c] for c in coins if c <= v and best[v - c] is not None]
        best[v] = min(opts) + 1 if opts else None
    return -1 if best[amount] is None else best[amount]

def solve(n: int) -> int:
    """Return the count of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes with O(n log log n) time.
    """
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    import math
    limit = int(math.isqrt(n - 1))
    for i in range(2, limit + 1):
        if sieve[i]:
            step = i
            start = i * i
            sieve[start:n:step] = [False] * ((n - 1 - start) // step + 1)
    return sum(sieve)

