def solve(n):
    if n < 2:
        return 0
    import math
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.isqrt(n - 1)) + 1):
        if is_prime[i]:
            for j in range(i * i, n, i):
                is_prime[j] = False
    return sum(1 for i in range(2, n) if is_prime[i])

